    (function () {
      const carousel = document.getElementById('trending-carousel');
      const prev = document.querySelector('.carousel-prev');
      const next = document.querySelector('.carousel-next');

      function scrollAmount() {
        return Math.max(220, Math.floor(carousel.clientWidth * 0.78));
      }

      prev.addEventListener('click', function () {
        carousel.scrollBy({ left: -scrollAmount(), behavior: 'smooth' });
      });

      next.addEventListener('click', function () {
        carousel.scrollBy({ left: scrollAmount(), behavior: 'smooth' });
      });

      const faqList = document.getElementById('faq-list');
      const items = Array.from(faqList.querySelectorAll('.faq-item'));

      faqList.addEventListener('click', function (event) {
        const button = event.target.closest('.faq-question');
        if (!button) return;

        const currentItem = button.parentElement;
        items.forEach(function (item) {
          const isTarget = item === currentItem;
          item.classList.toggle('open', isTarget);
          const question = item.querySelector('.faq-question');
          question.setAttribute('aria-expanded', String(isTarget));
        });
      });

      document.querySelectorAll('form').forEach(function (form) {
        form.addEventListener('submit', function (event) {
          const input = form.querySelector('input[type="email"]');
          if (!input || !input.value.trim()) {
            event.preventDefault();
            input && input.focus();
            return;
          }
          event.preventDefault();
        });
      });
    })();
  </script>
